SELECT order_id, customer
  FROM orders
 WHERE details ->> 'status' = 'shipped';

SELECT order_id, customer
  FROM orders
 WHERE (details #>> '{payment,amount}')::numeric > 1000;

SELECT order_id, customer
  FROM orders
 WHERE details @> '{"payment": {"method": "upi"}}';

SELECT order_id, customer
  FROM orders
 WHERE details @> '{"items": [{"sku": "PN-220"}]}';

SELECT order_id, customer FROM orders WHERE details -> 'tags' ? 'express';
SELECT order_id, customer FROM orders WHERE details -> 'tags' ?| array['gift', 'refund'];
SELECT order_id, customer FROM orders WHERE details -> 'tags' ?& array['gift', 'express'];

SELECT order_id, customer
  FROM orders
 WHERE details @? '$.items[*] ? (@.price > 400)';

SELECT order_id,
       jsonb_path_query(details, '$.items[*] ? (@.qty >= 2).sku') AS sku
  FROM orders;

SELECT order_id, customer
  FROM orders
 WHERE jsonb_path_exists(details, '$.items[*] ? (@.price > $min)', '{"min": 1000}');

BEGIN;

UPDATE orders
   SET details = jsonb_set(details, '{status}', '"delivered"')
 WHERE order_id = 1;

UPDATE orders
   SET details = jsonb_set(details, '{payment,txn_id}', '"UPI98231"')
 WHERE order_id = 1;

SELECT details -> 'status' AS status, details -> 'payment' AS payment
  FROM orders WHERE order_id = 1;

