UPDATE orders
   SET details['payment']['method'] = '"netbanking"'
 WHERE order_id = 2;

UPDATE orders
   SET details['tags'] = details['tags'] || '["vip"]'
 WHERE order_id = 2;

SELECT details['payment'] AS payment, details['tags'] AS tags
  FROM orders WHERE order_id = 2;

ROLLBACK;

EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, BUFFERS OFF)
SELECT order_id FROM orders_big
 WHERE details @> '{"items": [{"sku": "SKU-42"}]}';

CREATE INDEX orders_big_details_pathops
    ON orders_big USING GIN (details jsonb_path_ops);

SELECT indexrelname, pg_size_pretty(pg_relation_size(indexrelid)) AS size
  FROM pg_stat_user_indexes
 WHERE relname = 'orders_big'
 ORDER BY indexrelname;

DROP INDEX orders_big_details_gin;

EXPLAIN (COSTS OFF)
SELECT order_id FROM orders_big WHERE details ? 'coupon';

CREATE INDEX orders_big_status_idx ON orders_big ((details ->> 'status'));
CREATE INDEX orders_big_amount_idx
    ON orders_big (((details #>> '{payment,amount}')::numeric));
ANALYZE orders_big;

EXPLAIN (COSTS OFF)
SELECT order_id FROM orders_big
 WHERE (details #>> '{payment,amount}')::numeric > 5090;

